class AuditResource:
    """Console audit log."""

    def __init__(self, core: Core) -> None:
        self._core = core

    def list(self, *, action: Optional[str] = None, actor_id: Optional[str] = None, created_after: Optional[str] = None, created_before: Optional[str] = None, cursor: Optional[str] = None, format: Optional[Literal["json", "csv"]] = None, limit: Optional[int] = None, object_id: Optional[str] = None, object_type: Optional[str] = None, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> AuditListData:
        """Console audit log of the calling environment, newest first."""
        return self._core.call("GET", f"/v1/audit-logs", query={"action": action, "actor_id": actor_id, "object_type": object_type, "object_id": object_id, "created_after": created_after, "created_before": created_before, "limit": limit, "cursor": cursor, "format": format}, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def list_all(self, *, action: Optional[str] = None, actor_id: Optional[str] = None, object_type: Optional[str] = None, object_id: Optional[str] = None, created_after: Optional[str] = None, created_before: Optional[str] = None, limit: Optional[int] = None, format: Optional[Literal["json", "csv"]] = None, request_id: Optional[str] = None) -> Iterator[AuditEntry]:
        """Every item of list, page after page (follows next_cursor)."""
        return self._core.paginate(f"/v1/audit-logs", {"action": action, "actor_id": actor_id, "object_type": object_type, "object_id": object_id, "created_after": created_after, "created_before": created_before, "limit": limit, "format": format}, request_id=request_id)

    def list_verify(self, *, created_after: Optional[str] = None, created_before: Optional[str] = None, cursor: Optional[str] = None, format: Optional[Literal["json", "csv"]] = None, identifier: Optional[str] = None, job_id: Optional[str] = None, limit: Optional[int] = None, operation: Optional[Literal["aadhaar-offline", "bank-account", "cin", "docai/kyc/aadhaar", "docai/kyc/driving_licence", "docai/kyc/pan_card", "docai/kyc/passport", "docai/kyc/voter_id", "document-tamper", "driving-licence", "duplicate-document", "email", "face-match", "fssai", "gstin", "iec", "ifsc", "kyc", "liveness", "mobile", "pan", "pan-aadhaar-link", "passport", "udyam", "upi", "vehicle-rc", "voter-id"]] = None, reference_id: Optional[str] = None, result: Optional[Literal["valid", "invalid", "not_found", "inactive", "mismatch", "unavailable"]] = None, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> AuditListVerifyData:
        """The Verify audit log of the calling environment, newest first: one row per lookup, the identifier only as its fingerprint and last 4."""
        return self._core.call("GET", f"/v1/verify/audit", query={"operation": operation, "result": result, "identifier": identifier, "reference_id": reference_id, "job_id": job_id, "created_after": created_after, "created_before": created_before, "limit": limit, "cursor": cursor, "format": format}, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def list_verify_all(self, *, operation: Optional[Literal["aadhaar-offline", "bank-account", "cin", "docai/kyc/aadhaar", "docai/kyc/driving_licence", "docai/kyc/pan_card", "docai/kyc/passport", "docai/kyc/voter_id", "document-tamper", "driving-licence", "duplicate-document", "email", "face-match", "fssai", "gstin", "iec", "ifsc", "kyc", "liveness", "mobile", "pan", "pan-aadhaar-link", "passport", "udyam", "upi", "vehicle-rc", "voter-id"]] = None, result: Optional[Literal["valid", "invalid", "not_found", "inactive", "mismatch", "unavailable"]] = None, identifier: Optional[str] = None, reference_id: Optional[str] = None, job_id: Optional[str] = None, created_after: Optional[str] = None, created_before: Optional[str] = None, limit: Optional[int] = None, format: Optional[Literal["json", "csv"]] = None, request_id: Optional[str] = None) -> Iterator[VerifyAuditRow]:
        """Every item of list_verify, page after page (follows next_cursor)."""
        return self._core.paginate(f"/v1/verify/audit", {"operation": operation, "result": result, "identifier": identifier, "reference_id": reference_id, "job_id": job_id, "created_after": created_after, "created_before": created_before, "limit": limit, "format": format}, request_id=request_id)


class FilesResource:
    """Uploaded and produced files."""

    def __init__(self, core: Core) -> None:
        self._core = core

    def content_url(self, id: str, *, request_id: Optional[str] = None) -> str:
        """Redirect to a signed download link valid 1 hour."""
        return self._core.redirect(f"/v1/files/{_seg(id)}/content", request_id=request_id)

    def delete(self, id: str, *, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> Deleted:
        """Delete a file now."""
        return self._core.call("DELETE", f"/v1/files/{_seg(id)}", query=None, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def get(self, id: str, *, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> StoredFile:
        """File metadata."""
        return self._core.call("GET", f"/v1/files/{_seg(id)}", query=None, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def upload(self, file: FileInput, *, request_id: Optional[str] = None) -> StoredFile:
        """Upload a file (50 MB live, 5 MB test)."""
        return self._core.upload(f"/v1/files", file, request_id=request_id)

    def download(self, url: str) -> bytes:
        """Downloads a file object's signed url (no API key is sent)."""
        return self._core.download(url)


class JobsResource:
    """Asynchronous jobs."""

    def __init__(self, core: Core) -> None:
        self._core = core

    def cancel(self, id: str, *, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> Job:
        """Cancel a queued job, or a running one at its next checkpoint."""
        return self._core.call("POST", f"/v1/jobs/{_seg(id)}/cancel", query=None, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def events(self, id: str, *, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> JobsEventsData:
        """A job's timeline, oldest first (queued, processing, the end, with task ids)."""
        return self._core.call("GET", f"/v1/jobs/{_seg(id)}/events", query=None, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def events_all(self, id: str, *, request_id: Optional[str] = None) -> Iterator[JobEvent]:
        """Every item of events, page after page (follows next_cursor)."""
        return self._core.paginate(f"/v1/jobs/{_seg(id)}/events", {}, request_id=request_id)

    def get(self, id: str, *, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> Job:
        """Read a job; result has the shape the sync call would have returned."""
        return self._core.call("GET", f"/v1/jobs/{_seg(id)}", query=None, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def list(self, *, created_after: Optional[str] = None, created_before: Optional[str] = None, cursor: Optional[str] = None, key_id: Optional[str] = None, limit: Optional[int] = None, operation: Optional[str] = None, service: Optional[str] = None, status: Optional[Literal["queued", "processing", "succeeded", "failed", "cancelled"]] = None, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> JobsListData:
        """List jobs, newest first."""
        return self._core.call("GET", f"/v1/jobs", query={"status": status, "service": service, "operation": operation, "key_id": key_id, "created_after": created_after, "created_before": created_before, "limit": limit, "cursor": cursor}, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def list_all(self, *, status: Optional[Literal["queued", "processing", "succeeded", "failed", "cancelled"]] = None, service: Optional[str] = None, operation: Optional[str] = None, key_id: Optional[str] = None, created_after: Optional[str] = None, created_before: Optional[str] = None, limit: Optional[int] = None, request_id: Optional[str] = None) -> Iterator[Job]:
        """Every item of list, page after page (follows next_cursor)."""
        return self._core.paginate(f"/v1/jobs", {"status": status, "service": service, "operation": operation, "key_id": key_id, "created_after": created_after, "created_before": created_before, "limit": limit}, request_id=request_id)

    def wait(self, job_id: str, *, timeout: float = 300.0, max_interval: float = 10.0) -> Job:
        """Waits until the job is succeeded, failed or cancelled, polling with the Retry-After the API sends; raises LowcoJobError when it failed or was cancelled, LowcoTimeoutError at the timeout."""
        return self._core.wait_for_job(job_id, timeout=timeout, max_interval=max_interval)


